{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Modern Aromatherapy for Daily Rituals</title>
  <meta name="description" content="A safety-forward aromatherapy practice blending art and science for mindful living. Consultations, retail blends, and ritual kits.">
  <meta name="theme-color" content="#2b2a36">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="page-lux">
  <svg class="bg-pattern" aria-hidden="true"><use href="assets/img/pattern.svg#pattern"/></svg>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" id="mainNav" aria-label="Primary">
        <a href="/services.html">Offerings</a>
        <a href="/blends.html">Botanical Blends</a>
        <a href="/shop.html">Curated Shop</a>
        <a href="/about.html">Our Ethos</a>
        <a href="/book.html" class="cta">Book a Session</a>
      </nav>
      <button id="navToggle" class="nav-toggle" aria-expanded="false" aria-label="Toggle menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO: mystical modern intro -->
    <section class="hero wrap" id="hero">
      <div class="hero-grid">
        <div class="hero-copy">
          <h1 class="kicker">Aroma as Ritual</h1>
          <h2 class="title">Contemporary aromatherapy for gentle transformation</h2>
          <p class="lead">At {{BUSINESS_NAME}}, {{PRACTITIONER_NAME}} guides you through scent-forward rituals and safety-focused blends that support daily wellbeing. No medical claims — just intentional, informed aromatherapy.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/about.html">Meet {{PRACTITIONER_NAME}}</a>
          </div>
        </div>
        <div class="hero-visual" aria-hidden="true">
          <div class="v-Glass">
            <svg viewBox="0 0 200 200" class="bloom" xmlns="http://www.w3.org/2000/svg">
              <defs>
                <linearGradient id="g1" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stop-color="#EBD8FF"/>
                  <stop offset="100%" stop-color="#CDEFFF"/>
                </linearGradient>
                <filter id="blur"><feGaussianBlur stdDeviation="4"/></filter>
              </defs>
              <g fill="url(#g1)" filter="url(#blur)">
                <circle cx="60" cy="60" r="28" opacity="0.9"/>
                <ellipse cx="140" cy="80" rx="34" ry="26" opacity="0.85"/>
                <path d="M40 140 C70 110, 130 110, 160 140" stroke="#D1B3FF" stroke-width="6" fill="none" stroke-linecap="round"/>
              </g>
            </svg>
            <div class="drop">{{FAVORITE_BLEND}}</div>
          </div>
        </div>
      </div>
    </section>

    <!-- DIAGNOSTIC: simple scent profile quiz (no medical claims) -->
    <section class="diagnostic wrap" id="diagnostic">
      <h3 class="section-title">Scent discovery — a gentle diagnostic</h3>
      <p class="section-lead">This quick questionnaire helps identify scent families you prefer and notes safety considerations. This is not a medical assessment.</p>
      <form id="scentQuiz" class="quiz" novalidate>
        <div class="q-row">
          <label>Which aroma families feel most inviting?</label>
          <div class="chips">
            <button type="button" data-value="floral" class="chip">Floral</button>
            <button type="button" data-value="citrus" class="chip">Citrus</button>
            <button type="button" data-value="wood" class="chip">Woodsy</button>
            <button type="button" data-value="herbal" class="chip">Herbal</button>
            <button type="button" data-value="spice" class="chip">Warm & Spiced</button>
          </div>
        </div>

        <div class="q-row">
          <label>Are there any scent sensitivities or cautions to note?</label>
          <textarea id="sensitivities" name="sensitivities" placeholder="E.g., pregnant, asthma, pet sensitivities — or 'none'" rows="3"></textarea>
        </div>

        <div class="q-row actions">
          <button type="submit" class="btn primary">Suggest a starter plan</button>
          <button type="button" id="quizReset" class="btn ghost">Reset</button>
        </div>
      </form>
      <div id="quizResult" class="quiz-result" aria-live="polite"></div>
    </section>

    <!-- PLAN: suggestion with retail addon workflow -->
    <section class="plan wrap" id="plan">
      <h3 class="section-title">Your Seed Plan — a gentle, retail-ready path</h3>
      <p class="section-lead">Based on scent preferences, we craft a small, safe starter kit. All product suggestions come with dilution and patch-test instructions.</p>
      <div class="plan-grid">
        <div class="plan-card">
          <h4>Starter Ritual Kit</h4>
          <p class="muted">Sampler vials, roll-on base, and ritual guide.</p>
          <ul>
            <li>3 x 1ml sample blends</li>
            <li>10ml jojoba roll-on bottle</li>
            <li>Ritual & safety card</li>
          </ul>
          <div class="card-actions">
            <a href="/shop.html#kit" class="btn">View in shop</a>
            <a href="/book.html" class="btn ghost">Add a consult</a>
          </div>
        </div>
        <div class="plan-card highlighted">
          <h4>Personalized Blend</h4>
          <p class="muted">Formulated after a short consult. Suitable for topical (with dilution) and aromatic use.</p>
          <ul>
            <li>Top/Middle/Base notes listed</li>
            <li>Patch-test & dilution guide included</li>
            <li>Pet & pregnancy cautions reviewed</li>
          </ul>
          <div class="card-actions">
            <a href="/blends.html" class="btn">Browse blends</a>
            <a href="/book.html" class="btn ghost">Schedule</a>
          </div>
        </div>
      </div>
    </section>

    <!-- MICRO_HABITS: small rituals -->
    <section class="micro-habits wrap" id="micro_habits">
      <h3 class="section-title">Micro-habits — 2–5 minute scent rituals</h3>
      <p class="section-lead">Tiny, repeatable practices to fold aromatherapy into everyday life. Always follow dilution and safety guidance.</p>
      <ul class="habits-grid">
        <li>
          <h5>Morning Clarify</h5>
          <p>2–3 drops of citrus blend in diffuser for 10 minutes to refresh a room.</p>
        </li>
        <li>
          <h5>Calm Pause</h5>
          <p>Breathwork with a lavender roll-on applied to wrists (1% dilution).</p>
        </li>
        <li>
          <h5>Work Reset</h5>
          <p>Swipe a citrus-herb inhaler before deep-focus work sessions.</p>
        </li>
        <li>
          <h5>Sleep Wind-down</h5>
          <p>Diffuse a low-intensity chamomile-woody blend 30 minutes before bed.</p>
        </li>
      </ul>
    </section>

    <!-- PRICING: sample tiers (retail_addon) -->
    <section class="pricing wrap" id="pricing">
      <h3 class="section-title">Pricing & Add-ons</h3>
      <p class="section-lead">Transparent pricing for sessions, blends, and curated retail kits.</p>
      <div class="pricing-toggle">
        <label><input type="radio" name="billing" value="one" checked> One-time</label>
        <label><input type="radio" name="billing" value="sub"> Subscription (save 10%)</label>
      </div>
      <div class="pricing-grid">
        <div class="price-card">
          <h4>Discovery Session</h4>
          <div class="price">$65</div>
          <p class="desc">30-minute consult — scent preferences & safety review.</p>
          <a href="/book.html" class="btn">Book</a>
        </div>
        <div class="price-card popular">
          <h4>Custom Blend</h4>
          <div class="price">$95</div>
          <p class="desc">Personalized 10ml blend with instructions and refill option.</p>
          <a href="/blends.html" class="btn">Request</a>
        </div>
        <div class="price-card">
          <h4>Starter Kit</h4>
          <div class="price">$48</div>
          <p class="desc">Sampler kit — perfect introduction. Buy in shop.</p>
          <a href="/shop.html#kit" class="btn">Shop</a>
        </div>
      </div>
      <p class="safety-note">All topical recommendations include dilution instructions. Consultations include pet and pregnancy precautions; we never provide medical advice.</p>
    </section>

    <!-- CTA: booking and contact -->
    <section class="cta wrap" id="cta">
      <div class="cta-inner">
        <div>
          <h3>Ready to layer scent into your days?</h3>
          <p>Book a short discovery session or browse our shop for safe, small-batch blends.</p>
        </div>
        <div class="cta-actions">
          <a href="{{PRIMARY_CTA_URL}}" class="btn primary">{{PRIMARY_CTA_LABEL}}</a>
          <a href="/contact.html" class="btn ghost">Contact</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div class="f-brand">
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">{{TAGLINE}}</p>
      </div>
      <div>
        <h5>Visit & Contact</h5>
        <p class="muted">{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p class="muted"><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div>
        <h5>Explore</h5>
        <nav class="foot-nav">
          <a href="/services.html">Offerings</a>
          <a href="/blends.html">Blends</a>
          <a href="/shop.html">Shop</a>
          <a href="/about.html">About</a>
        </nav>
      </div>
    </div>
    <div class="legal">© <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved.</div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
