{"path":"assets/css/styles.css","content":"/* Core styles — mystic_modern + lux_gallery */
:root{
  --bg:#0f0e14;
  --card:#121018;
  --muted:#bfc2d7;
  --accent1:#9b6bff;
  --accent2:#6fd9ff;
  --glass: rgba(255,255,255,0.04);
  --radius:14px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#e8eaf6;background:linear-gradient(180deg,#0b0910 0%, #121018 60%);background-attachment:fixed;}
.wrap{max-width:1100px;margin:0 auto;padding:48px 20px}
.site-header{position:sticky;top:0;backdrop-filter:blur(6px);z-index:60;background:linear-gradient(180deg,rgba(11,9,16,0.6),rgba(11,9,16,0.35));border-bottom:1px solid rgba(255,255,255,0.03)}
.site-header .wrap{display:flex;align-items:center;gap:20px}
.brand{color:#fff;font-weight:700;text-decoration:none;font-size:1.05rem;letter-spacing:0.6px}
.main-nav{margin-left:auto;display:flex;gap:18px;align-items:center}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:10px}
.main-nav a.cta{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#08121a}
.nav-toggle{display:none;background:none;border:0;color:#fff;font-size:1.25rem}
.bg-pattern{position:fixed;inset:0;width:100%;height:100%;pointer-events:none;opacity:0.12}

/* HERO */
.hero{padding:72px 20px 56px}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:40px;align-items:center}
.kicker{color:var(--accent2);font-weight:600;margin:0}
.title{font-size:2.1rem;margin:12px 0 8px}
.lead{color:var(--muted);line-height:1.5}
.hero-actions{display:flex;gap:12px;margin-top:18px}
.btn{display:inline-block;padding:10px 16px;border-radius:12px;text-decoration:none;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#051018}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted)}
.hero-visual .v-Glass{background:linear-gradient(135deg,rgba(255,255,255,0.03),rgba(255,255,255,0.01));padding:28px;border-radius:18px;box-shadow:0 6px 30px rgba(0,0,0,0.6);text-align:center}
.hero-visual .bloom{width:100%;height:180px}
.hero-visual .drop{margin-top:10px;color:var(--muted)}

/* DIAGNOSTIC */
.diagnostic{background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);border-radius:var(--radius);padding:28px;margin-top:20px}
.section-title{font-size:1.15rem;margin:0 0 8px}
.section-lead{color:var(--muted);margin-bottom:18px}
.quiz .q-row{margin-bottom:12px}
.chips{display:flex;flex-wrap:wrap;gap:10px}
.chip{background:var(--glass);color:var(--muted);border:1px solid rgba(255,255,255,0.03);padding:8px 12px;border-radius:999px}
.chip.active{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#071018}
textarea{width:100%;background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted);padding:10px;border-radius:10px}
.quiz-result{margin-top:14px;color:var(--muted)}

/* PLAN */
.plan{margin-top:30px}
.plan-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.plan-card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
.plan-card.highlighted{outline:2px solid rgba(159,111,255,0.12)}
.plan-card h4{margin:0 0 6px}
.plan-card .muted{color:var(--muted);margin:0 0 8px}
.card-actions{display:flex;gap:10px;margin-top:12px}

/* MICRO HABITS */
.micro-habits{margin-top:30px}
.habits-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;list-style:none;padding:0}
.habits-grid li{background:var(--card);padding:14px;border-radius:10px;border:1px solid rgba(255,255,255,0.02)}
.habits-grid h5{margin:0 0 6px}

/* PRICING */
.pricing{margin-top:30px}
.pricing-toggle{display:flex;gap:12px;margin-bottom:12px}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.price-card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:12px;text-align:center}
.price-card.popular{box-shadow:0 8px 24px rgba(107,71,255,0.08);transform:translateY(-4px)}
.price{font-size:1.5rem;font-weight:700;margin:8px 0}
.safety-note{color:var(--muted);font-size:0.9rem;margin-top:12px}

/* CTA */
.cta{margin:40px 0;padding:22px;border-radius:12px;background:linear-gradient(90deg,rgba(155,107,255,0.08),rgba(111,217,255,0.03));display:flex;align-items:center}
.cta-inner{display:flex;justify-content:space-between;gap:20px;width:100%;align-items:center}
.cta-actions{display:flex;gap:10px}

/* FOOTER */
.site-footer{padding:28px 0 60px;color:var(--muted)}
.footer-grid{display:flex;gap:28px;align-items:flex-start}
.legal{margin-top:18px;color:#8f8ea6}

/* Responsive */
@media(max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .main-nav{display:none}
  .nav-toggle{display:block;margin-left:auto}
  .plan-grid{grid-template-columns:1fr}
  .habits-grid{grid-template-columns:1fr}
  .pricing-grid{grid-template-columns:1fr}
}

/* Small utilities */
.muted{color:var(--muted)}
.hidden{display:none}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Simple UI behaviors: nav toggle, chips, quiz, pricing toggle, year
  document.addEventListener('DOMContentLoaded',function(){
    // year
    var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

    // nav toggle
    var navToggle=document.getElementById('navToggle');
    var mainNav=document.getElementById('mainNav');
    navToggle&&navToggle.addEventListener('click',function(){
      var expanded=this.getAttribute('aria-expanded')==='true';
      this.setAttribute('aria-expanded',!expanded);
      mainNav.style.display = expanded? 'none':'flex';
    });

    // chips for scent quiz
    var chips=document.querySelectorAll('.chip');
    var selected=new Set();
    chips.forEach(function(c){
      c.addEventListener('click',function(){
        var v=this.getAttribute('data-value');
        if(this.classList.contains('active')){ this.classList.remove('active'); selected.delete(v); }
        else{ this.classList.add('active'); selected.add(v); }
      });
    });

    // quiz form
    var quiz=document.getElementById('scentQuiz');
    var result=document.getElementById('quizResult');
    var reset=document.getElementById('quizReset');
    reset&&reset.addEventListener('click',function(){
      chips.forEach(function(c){c.classList.remove('active')}); selected.clear(); document.getElementById('sensitivities').value=''; result.textContent='';
    });

    quiz&&quiz.addEventListener('submit',function(e){
      e.preventDefault();
      var sens=document.getElementById('sensitivities').value.trim();
      var picks=Array.from(selected);
      if(picks.length===0){ result.textContent='Pick at least one aroma family to receive a starter suggestion.'; return; }
      // build gentle plan suggestion (no medical claims)
      var profile = picks.join(', ');
      var note = sens? ('Noted cautions: '+sens+'.') : 'No cautions noted.';
      var suggestion = 'Suggested starter scent family: '+profile+". " + note + ' We recommend a starter kit with sample vials and a 1% topical dilution guide. For pregnancy or severe sensitivities, schedule a consult.';
      result.textContent = suggestion;
      // optional gentle UX: highlight plan card
      var pc=document.querySelector('.plan-card.highlighted'); if(pc){ pc.classList.add('pulse'); setTimeout(function(){pc.classList.remove('pulse')},1200); }
    });

    // pricing toggle stub
    var billingRadios=document.querySelectorAll('input[name="billing"]');
    billingRadios.forEach(function(r){ r.addEventListener('change',function(){
      var sub=this.value==='sub';
      document.querySelectorAll('.price').forEach(function(p){
        var base=parseFloat(p.textContent.replace('$',''))||0;
        if(sub) p.textContent = '$'+(Math.round(base*0.9)); else p.textContent = '$'+base;
      });
    })});

    // small accessibility: ensure nav hides on resize >880
    window.addEventListener('resize',function(){ if(window.innerWidth>880){ mainNav.style.display='flex'; } else { mainNav.style.display='none'; navToggle && navToggle.setAttribute('aria-expanded','false'); } });

    // micro-habits checkbox interactions (progressive enhancement)
    var habitItems=document.querySelectorAll('.habits-grid li');
    habitItems.forEach(function(li){ li.addEventListener('click',function(){ li.classList.toggle('done'); }); });

    // simple local link protection: validate CTA URL placeholder
    var primary = document.querySelector('.btn.primary');
    if(primary && primary.getAttribute('href').includes('{{')){ primary.addEventListener('click',function(e){ e.preventDefault(); alert('Please set your primary CTA URL in site settings before publishing.'); }); }
  });
})();"} 
